<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/helpers.php';
requerirRol(['departamento']);
requerirCorreoConfirmado($pdo); $u=usuarioActual();
if(!$u['departamento_id']){die('Tu cuenta no tiene un departamento asociado. Contacta al administrador.');}
$q=$pdo->prepare("SELECT COUNT(*) FROM tickets WHERE departamento_id=? AND estado IN ('pendiente','asignado','en_proceso')");$q->execute([$u['departamento_id']]);$abiertos=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT t.*,a.usuario AS analista_usuario,TRIM(CONCAT(COALESCE(ap.nombre,''),' ',COALESCE(ap.apellido,''))) AS analista_nombre FROM tickets t LEFT JOIN usuarios a ON a.id_usuarios=t.analista_id LEFT JOIN perfiles_usuarios ap ON ap.usuario_id=a.id_usuarios WHERE t.departamento_id=? ORDER BY t.fecha_creacion DESC LIMIT 8");$q->execute([$u['departamento_id']]);$tickets=$q->fetchAll();
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi oficina | Soporte Técnico</title><link rel="icon" href="../assets/img/logo.png"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH" crossorigin="anonymous"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet" integrity="sha384-tViUnnbYAV00FLIhhi3v/dWt3Jxw4gZQcNoSCxCIFNJVCx7/D55/wXsrNIRANwdD" crossorigin="anonymous"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="app-shell"><?php include __DIR__ . '/../includes/sidebar.php'; ?><div class="main"><?php include __DIR__.'/../includes/topbar.php'; ?><div class="content"><div class="d-flex justify-content-between align-items-center mb-4 department-page-header"><div><h2>Panel de <?=h($u['departamento_nombre']?:'oficina')?></h2><p class="text-muted mb-0">Solicita asistencia técnica y consulta el estado de tus tickets.</p></div></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="kpi-card"><div class="kpi-icon" style="background:var(--teal-100);color:var(--teal-700)"><i class="bi bi-ticket-detailed"></i></div><div class="kpi-label mt-2">Tickets abiertos</div><div class="kpi-value"><?=$abiertos?></div></div></div></div><div class="department-new-ticket"><a href="crear_ticket.php" class="btn btn-brand"><i class="bi bi-plus-circle me-1"></i> Nuevo ticket</a></div><div class="card-panel"><div class="panel-head"><h2>Mis últimos tickets</h2><a href="mis_tickets.php" class="small">Ver todos</a></div><div class="panel-body"><?php if(!$tickets): ?><p class="text-muted mb-0">Todavía no has creado tickets.</p><?php endif; ?><?php foreach($tickets as $t): ?><a class="ticket-card text-decoration-none text-reset mb-2" href="ver_ticket.php?id=<?=(int)$t['id_tickets']?>"><div class="ticket-stub st-proceso"><span>#<?=str_pad((string)$t['id_tickets'],6,'0',STR_PAD_LEFT)?></span></div><div class="ticket-body"><div class="t-top"><p class="t-title"><?=h($t['titulo'])?></p><span class="badge <?= $t['estado']==='completado'?'badge-completado':($t['estado']==='pendiente'?'badge-pendiente':'badge-proceso') ?>"><?=h(ucfirst(str_replace('_',' ',$t['estado'])))?></span></div><div class="t-meta"><?=date('d/m/Y H:i',strtotime($t['fecha_creacion']))?> · <?= $t['analista_nombre']? 'Analista: '.h($t['analista_nombre']) : 'Sin asignar' ?></div></div></a><?php endforeach; ?></div></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js" integrity="sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz" crossorigin="anonymous"></script></body></html>